-- Guarded cleanup of inert legacy resource child pools, batch 09.
-- Physical gameobject rows are untouched.
START TRANSACTION;
DELETE pp FROM pool_pool pp LEFT JOIN pool_creature pc ON pc.pool_entry=pp.pool_id LEFT JOIN pool_gameobject pg ON pg.pool_entry=pp.pool_id LEFT JOIN pool_quest pq ON pq.pool_entry=pp.pool_id LEFT JOIN game_event_pool gep ON gep.pool_entry=pp.pool_id LEFT JOIN pool_pool child ON child.mother_pool=pp.pool_id WHERE pp.pool_id IN (2352,2353,2355,2356,2357,2358,2359,2360,2361,2362,2363,2364,2366,2368,2370,2371,2372,2373,2374,2375,2376,2377,2378,2379,2384,2385,2386,2387,2389,2390,2391,2392,2393,2394,2395,2396,2399,2400,2404,2405,2406,2407,2408,2409,2410,2411,2412,2413,2414,2415) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND child.pool_id IS NULL;
DELETE pt FROM pool_template pt LEFT JOIN pool_creature pc ON pc.pool_entry=pt.entry LEFT JOIN pool_gameobject pg ON pg.pool_entry=pt.entry LEFT JOIN pool_quest pq ON pq.pool_entry=pt.entry LEFT JOIN game_event_pool gep ON gep.pool_entry=pt.entry LEFT JOIN pool_pool pp_child ON pp_child.pool_id=pt.entry LEFT JOIN pool_pool pp_mother ON pp_mother.mother_pool=pt.entry WHERE pt.entry IN (2352,2353,2355,2356,2357,2358,2359,2360,2361,2362,2363,2364,2366,2368,2370,2371,2372,2373,2374,2375,2376,2377,2378,2379,2384,2385,2386,2387,2389,2390,2391,2392,2393,2394,2395,2396,2399,2400,2404,2405,2406,2407,2408,2409,2410,2411,2412,2413,2414,2415) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND pp_child.pool_id IS NULL AND pp_mother.pool_id IS NULL;
COMMIT;

